const W_DROP = 15267056;
const W_DROP_MID = 9091256;
const W_DROP_TAIL = 4881028;
const W_FOAM = 15003884;
const W_FOAM_EDGE = 7249572;
const W_BUBBLE = 13624540;
const W_BUBBLE_IN = 5933714;
